{
    Map m;
    CHECK(m[K("exit")] == 0u);
    m[K("exit")] = 12u;
    m[K("bridge")] = 3u;
    CHECK(m[K("exit")] == 12u && m[K("bridge")] == 3u && m.count == 2);
    CHECK(std::strcmp(m.head->first.s, "bridge") == 0);
    std::printf("00cd39b1_TEST PASS\n");
    return 0;
